// ============================================================================
// test_mail.cpp — email / document readers on SYNTHETIC fixtures
// (tests/data/mail, generated by tools/make_mail_fixtures.py):
//   * MIME primitives: QP, base64, RFC 2047, RFC 2231, charsets
//   * EML: multipart/mixed + alternative + related, cid image, nested
//     message/rfc822, path-stripped names, windows-1250 body
//   * MSG: CFB (mini + regular streams), recipients, attachments, embedded
//     message, LZFu RTF with encapsulated HTML; string8 + plain RTF body
//   * HTML -> rich (scripts dropped, remote images not loaded), RTF reader /
//     writer round trip, DOCX reader
// ============================================================================
#include "../src/io/docx.h"
#include "../src/io/mail_eml.h"
#include "../src/io/mail_msg.h"
#include "../src/io/mime.h"
#include "../src/io/richdoc.h"
#include "../src/io/rtf.h"
#include <cstdio>
#include <cstring>
#include <fstream>
#include <iterator>
#include <string>
#include <vector>

using namespace pcbp::io;

static int g_fail = 0, g_n = 0;
#define CHECK(c) do { ++g_n; if (!(c)) { ++g_fail; std::printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #c); } } while (0)

static std::vector<uint8_t> load(const char* n) {
    std::ifstream f(std::string("tests/data/mail/") + n, std::ios::binary);
    return std::vector<uint8_t>(std::istreambuf_iterator<char>(f), {});
}
static bool has(const std::string& s, const char* k) { return s.find(k) != std::string::npos; }

static void test_mime() {
    CHECK(decode_encoded_words("=?ISO-8859-1?Q?Andr=E9?= x") == "Andr\xC3\xA9 x");
    CHECK(decode_encoded_words("=?UTF-8?Q?a?= =?UTF-8?Q?b?=") == "ab");          // adjacent words join
    CHECK(decode_encoded_words("=?utf-8?B?w4l0aWVubmU=?=") == "\xC3\x89tienne");
    auto q = qp_decode("a=3Db=\r\nc");
    CHECK(std::string(q.begin(), q.end()) == "a=bc");
    auto b = base64_decode("SGVs\r\nbG8=");
    CHECK(std::string(b.begin(), b.end()) == "Hello");
    HeaderValue hv = parse_header_value("attachment; filename*0*=utf-8''St%C3%BCck; filename*1=\"liste.csv\"");
    CHECK(hv.value == "attachment");
    CHECK(hv.param("filename") == "St\xC3\xBC" "ckliste.csv");
    CHECK(charset_to_utf8("\x8A", "windows-1250") == "\xC5\xA0");               // S caron
    CHECK(charset_to_utf8("\xE9", "iso-8859-1") == "\xC3\xA9");
    CHECK(charset_to_utf8("\xC0", "windows-1251") == "\xD0\x90");               // Cyrillic A
    CHECK(charset_to_utf8("\xE9t\xE9", "x-unknown") == "\xC3\xA9t\xC3\xA9");      // fallback 1252
    CHECK(charset_to_utf8("\xC3\xA9", "x-unknown") == "\xC3\xA9");              // fallback valid UTF-8
}

static void test_eml() {
    auto d = load("sample1.eml");
    CHECK(!d.empty());
    CHECK(is_eml_bytes(d.data(), d.size()));
    MailMessage m;
    std::string err;
    CHECK(eml_parse(d, m, err));
    CHECK(m.from == "Andr\xC3\xA9 Example <andre@example.com>");
    CHECK(has(m.to, "carol@example.com"));
    CHECK(has(m.cc, "\xC3\x89tienne"));
    CHECK(m.subject == "Gerbers + BOM \xE2\x80\x94 rev C");
    CHECK(has(m.date, "14 Mar 2026"));
    CHECK(has(m.text, "Caf\xC3\xA9 soft break."));
    CHECK(has(m.html, "<h1>Heading</h1>"));
    // attachments: logo (inline, related), csv (2231 name), zip (2047 name), nested message
    CHECK(m.atts.size() == 4);
    if (m.atts.size() == 4) {
        CHECK(m.atts[0].name == "logo.png" && m.atts[0].inline_part && m.atts[0].cid == "logo@cid");
        CHECK(m.atts[0].data.size() > 8 && m.atts[0].data[1] == 'P');
        CHECK(m.atts[1].name == "St\xC3\xBC" "ckliste.csv");
        CHECK(std::string(m.atts[1].data.begin(), m.atts[1].data.end()) == "Ref,Qty\nR1,2\n");
        CHECK(m.atts[2].name == "gerbers r\xC3\xA9v.zip" && m.atts[2].data[0] == 'P' && m.atts[2].data[1] == 'K');
        CHECK(m.atts[3].embedded != nullptr);
        if (m.atts[3].embedded) {
            const MailMessage& in = *m.atts[3].embedded;
            CHECK(in.subject == "Original request");
            CHECK(has(in.text, "Inner body"));
            CHECK(in.atts.size() == 1 && in.atts[0].name == "notes.txt");   // "../../evil/" stripped
            CHECK(m.atts[3].name == "Original request.eml");
        }
    }
    // HTML body -> rich text: cid image resolved, remote ones not, scripts / title / style gone
    RichDoc rd;
    int cid_calls = 0;
    html_to_rich(m.html, rd, [&](const std::string& cid) { ++cid_calls; if (cid == "logo@cid") { rd.images.push_back({"logo.png", "image/png", cid, m.atts[0].data}); return (int)rd.images.size() - 1; } return -1; });
    std::string pl = rd.plain();
    CHECK(cid_calls == 1);
    CHECK(!has(pl, "document.write") && !has(pl, ".a{}"));
    CHECK(has(pl, "Heading") && has(pl, "Hello bold it link & \xE2\x82\xAC \xC3\xA9"));
    CHECK(has(pl, "remote, not loaded"));
    CHECK(!has(pl, "tracker"));
    CHECK(rd.tables.size() == 1 && rd.tables[0].rows.size() == 2);
    bool bullet = false, numbered2 = false, red = false, link = false, img = false;
    for (auto& p : rd.paras) {
        if (p.list == 1 && p.text() == "one") bullet = true;
        if (p.list == 2 && p.num == 2 && p.text() == "second") numbered2 = true;
        for (auto& r : p.runs) {
            if (r.color == 0xFFFF0000 && r.b) red = true;
            if (r.link == "https://example.com/q") link = true;
            if (r.image == 0) img = true;
        }
    }
    CHECK(bullet && numbered2 && red && link && img);
    // windows-1250 single part
    MailMessage m2;
    CHECK(eml_parse(load("sample_1250.eml"), m2, err));
    CHECK(m2.subject == "\xC5\xA0koda \xC5\xBE" "a");
    CHECK(has(m2.text, "P\xC5\x99\xC3\xAD" "li\xC5\xA1 \xC5\xBElu\xC5\xA5ou\xC4\x8Dk\xC3\xBD k\xC5\xAF\xC5\x88"));
    // writer round trip
    MailMessage m3;
    std::string w = eml_write(m);
    CHECK(eml_parse(std::vector<uint8_t>(w.begin(), w.end()), m3, err));
    CHECK(m3.subject == m.subject && m3.atts.size() == m.atts.size());
    if (m3.atts.size() == 4) CHECK(m3.atts[2].data == m.atts[2].data && m3.atts[3].embedded);
    CHECK(safe_attachment_name(MailAttachment{"con.txt", "", "", {}, false, nullptr}, 0) == "_con.txt");
    CHECK(safe_attachment_name(MailAttachment{"a:b?.pdf", "", "", {}, false, nullptr}, 0) == "a_b_.pdf");
}

static void test_msg() {
    auto d = load("sample1.msg");
    CHECK(is_cfb_bytes(d.data(), d.size()));
    MailMessage m;
    std::string err;
    bool ok = msg_parse(d, m, err);
    CHECK(ok);
    if (!ok) { std::printf("  msg err: %s\n", err.c_str()); return; }
    CHECK(m.subject == "Quote \xE2\x80\x94 BOM rev B \xE2\x9C\x93");
    CHECK(m.from == "Alice Example <alice@example.com>");
    CHECK(m.to == "Bob Builder <bob@example.com>");
    CHECK(m.cc == "Carol QA <carol@example.com>");
    CHECK(m.date == "2026-03-14 09:26 UTC");
    CHECK(has(m.text, "Hello World plain body"));
    CHECK(has(m.rtf, "\\fromhtml1"));
    CHECK(has(m.html, "<p>Hello <b>World</b> &amp; caf\xC3\xA9</p>"));
    CHECK(has(m.html, "<img src=\"cid:img1@example\">"));
    CHECK(!has(m.html, "\\htmlrtf"));
    CHECK(m.atts.size() == 4);
    if (m.atts.size() == 4) {
        CHECK(m.atts[0].name == "bom.csv" && m.atts[0].mime == "text/csv" && has(std::string(m.atts[0].data.begin(), m.atts[0].data.end()), "C5,1,100n 0402"));
        CHECK(m.atts[1].cid == "img1@example" && m.atts[1].inline_part && m.atts[1].data.size() > 20);
        CHECK(m.atts[2].data.size() == 10000);
        bool pat = m.atts[2].data.size() == 10000;
        for (int i = 0; pat && i < 10000; ++i) pat = m.atts[2].data[i] == (uint8_t)((i * 7 + 3) & 255);
        CHECK(pat);
        CHECK(m.atts[3].embedded != nullptr);
        if (m.atts[3].embedded) {
            CHECK(m.atts[3].embedded->subject == "Inner message");
            CHECK(m.atts[3].embedded->from == "Dave Inner");
            CHECK(m.atts[3].embedded->atts.size() == 1 && m.atts[3].embedded->atts[0].name == "inner.txt");
            CHECK(m.atts[3].name == "Inner message.msg");
            MailMessage back;
            CHECK(eml_parse(m.atts[3].data, back, err) && back.subject == "Inner message");   // savable as .eml
        }
    }
    MailMessage m2;
    CHECK(msg_parse(load("sample2.msg"), m2, err));
    CHECK(m2.subject == "R\xC3\xA9union planning");
    CHECK(m2.html.empty() && !m2.rtf.empty());
    RichDoc rd;
    CHECK(rtf_to_rich(m2.rtf, rd, err));
    std::string pl = rd.plain();
    CHECK(has(pl, "Bold normal italic red caf\xC3\xA9 \xE2\x82\xAC"));
    CHECK(has(pl, "link text"));
    CHECK(has(pl, "A1\tB1") && has(pl, "A2\tB2") && has(pl, "after"));
    bool bold = false, red = false, link = false;
    for (auto& p : rd.paras) for (auto& r : p.runs) {
        if (r.b && r.text == "Bold") bold = true;
        if (r.color == 0xFFFF0000 && r.text == "red") red = true;
        if (r.link == "https://example.com/x") link = true;
    }
    CHECK(bold && red && link);
    // non-message OLE2 is rejected
    std::vector<uint8_t> junk(1024, 0);
    CHECK(!msg_parse(junk, m2, err));
    // LZFu "MELA" stored form
    std::string st = std::string("\x0b\0\0\0\x05\0\0\0MELA\0\0\0\0", 16) + "{\\rtf}";
    std::string o;
    CHECK(lzfu_decompress((const uint8_t*)st.data(), st.size(), o, err) && o == "{\\rtf");
}

static void test_rtf_docx() {
    RichDoc d;
    RichPara p;
    RichRun a; a.text = "Hello "; p.runs.push_back(a);
    RichRun b; b.text = "w\xC3\xB6rld \xE2\x82\xAC"; b.b = true; b.color = 0xFF0000FF; b.size = 14; p.runs.push_back(b);
    d.paras.push_back(p);
    RichPara l; l.list = 1; RichRun lr; lr.text = "item {x}"; l.runs.push_back(lr); d.paras.push_back(l);
    RichPara k; RichRun kr; kr.text = "site"; kr.link = "https://example.com"; k.runs.push_back(kr); d.paras.push_back(k);
    std::string rtf = rich_to_rtf(d);
    RichDoc back;
    std::string err;
    CHECK(rtf_to_rich(rtf, back, err));
    CHECK(back.paras.size() == 3);
    if (back.paras.size() == 3) {
        CHECK(back.paras[0].text() == "Hello w\xC3\xB6rld \xE2\x82\xAC");
        CHECK(back.paras[0].runs.size() == 2 && back.paras[0].runs[1].b && back.paras[0].runs[1].color == 0xFF0000FF && back.paras[0].runs[1].size == 14);
        CHECK(back.paras[1].list == 1 && back.paras[1].text() == "item {x}");
        CHECK(back.paras[2].runs.size() == 1 && back.paras[2].runs[0].link == "https://example.com");
    }
    auto dx = load("sample1.docx");
    CHECK(is_docx_bytes(dx));
    RichDoc w;
    CHECK(docx_read(dx, w, err));
    std::string pl = w.plain();
    CHECK(has(pl, "Assembly notes") && has(pl, "Plain bold red italic 14"));
    CHECK(has(pl, "1. Step one") && has(pl, "2. Step two"));
    CHECK(has(pl, "Ref\tQty") && has(pl, "U1\t1"));
    CHECK(has(pl, "inserted") && !has(pl, "deleted"));
    CHECK(w.images.size() == 1 && w.images[0].mime == "image/png");
    CHECK(w.paras.size() > 0 && w.paras[0].heading == 1);
    bool link = false, red = false;
    for (auto& p2 : w.paras) for (auto& r : p2.runs) { if (r.link == "https://example.com/ds.pdf") link = true; if (r.color == 0xFFFF0000 && r.i && r.size == 14) red = true; }
    CHECK(link && red);
}

int main() {
    test_mime();
    test_eml();
    test_msg();
    test_rtf_docx();
    std::printf("mail: %d/%d checks passed\n", g_n - g_fail, g_n);
    return g_fail ? 1 : 0;
}
